from pathlib import Path

core = Path("core/core-rule-full.md")
c = core.read_text(encoding="utf-8")
old_neg = """## 【ネゴシエーション】
戦闘中、「敵戦闘集団」が１体だけになったとき、または「高脅威目標」の生命点が1になったときに使用できます。  
この技能を使用した場合、【指揮ロール】を行います。  
達成値が敵のレベル以上だった場合、対象を【捕虜】にすることができます。  
通常、捕虜を確保するために必要な拘束手段は不要とします。  
この技能は、「敵戦闘集団」が撤退した場合にも１度だけ使用することができます。  
成功した場合、その敵兵を捕虜とします。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
その裁定はシナリオに従います。
"""
new_neg = """## 【ネゴシエーション】
戦闘中、「敵戦闘集団」が１体だけになったとき、または「高脅威目標」の生命点が1になったときに使用できます。  
高脅威目標に使用できるのは、人物、または人間の乗員・操作員が介在する車両や固定兵装など、意思疎通可能な相手が存在する対象です。バリケード、無人設備、無人兵器など、人が介在しない対象には使用できません。  
この技能を使用した場合、【指揮ロール】を行います。  
達成値が敵のレベル以上だった場合、人物を対象とした場合は【捕虜】にできます。有人車両や有人固定兵装などを対象とした場合は、乗員・操作員を【捕虜】にし、その装備を【鹵獲】できます。乗員・操作員の人数がシナリオに記載されていない場合、捕虜人数を参照する効果では1名として扱います。  
【捕虜】または【鹵獲】となった対象は即座に戦闘から除外し、以後は行動・攻撃を行いません。他の敵が残っている場合、戦闘はそのまま継続します。  
通常、捕虜を確保するために必要な拘束手段は不要とします。  
この技能は、「敵戦闘集団」が撤退した場合にも１度だけ使用することができます。  
成功した場合、その敵兵を捕虜とします。  
この技能は、狂信的な敵や任務遂行のみを目的とする一部の敵には効果を発揮しません。  
その裁定はシナリオに従います。

### ■ 【鹵獲】

【鹵獲】は、撃破せずに確保した有人車両・有人固定兵装などを一時的に利用する処理です。高脅威目標の生命点が1の時点で【ネゴシエーション】に成功した場合に成立します。生命点が0になって撃破・破壊された装備は【鹵獲】できません。  
【鹵獲】した対象から得る通常の戦利品は、シナリオに別記がない限り通常どおり獲得できます。シナリオに固有の【鹵獲】効果が記載されている場合は、その記載を優先します。

- 【車両】  
  d66でマップを決定するシナリオでは、次の固定イベント（中間イベントまたは最終イベント）に到達するまで、マップ決定のd66を振った後、一の位を+1または-1できます。1回のマップ決定につき1回まで使用でき、一の位は1～6の範囲を超えません。強制される修正・固定・振り直し等を処理した後、この効果を適用して最終結果を確定します。この補正後の出目を、固定イベントの出現判定を含む以後の処理に使用します。次の固定イベントに到達した時点で車両の【鹵獲】効果は終了します。固定イベントやd66を使用しないシナリオでは、シナリオに記載された固有効果を使用します。  
  同時に保持できる【鹵獲】車両の効果は1台分だけです。新たな車両を【鹵獲】した場合、どちらを使用するか選び、選ばなかった車両から追加のd66補正は得られません。
- 【固定兵装】  
  使用可能な弾薬や部品を回収し、即座に弾倉+1個を得ます。その後、その固定兵装は使用不能になったものとして扱い、継続的な効果は持ちません。
- 1つの対象が【車両】と【固定兵装】の両方に該当する場合、特記がない限り【車両】の【鹵獲】効果だけを適用し、弾倉+1個は重複して得ません。
"""
if c.count(old_neg) != 1:
    raise SystemExit(f"negotiation anchor count={c.count(old_neg)}")
c = c.replace(old_neg, new_neg, 1)
core.write_text(c, encoding="utf-8")

scenario = Path("scenarios/missions/d66_lvl10-16_mission_01_blacksun.md")
s = scenario.read_text(encoding="utf-8")

# Make the two gun trucks machine-readable as vehicles.
for old, new in [
    ("##### 出目65 <つぎはぎだらけの武装トラック>\n\n- 属性：屋外、装甲", "##### 出目65 <つぎはぎだらけの武装トラック>\n\n- 属性：屋外、車両、装甲"),
    ("##### 出目66 <即席装甲ガン・トラック>\n\n- 属性：屋外、装甲", "##### 出目66 <即席装甲ガン・トラック>\n\n- 属性：屋外、車両、装甲"),
]:
    if s.count(old) != 1:
        raise SystemExit(f"vehicle attribute anchor count={s.count(old)} for {old[:30]}")
    s = s.replace(old, new, 1)

old65 = """- 機銃制圧：
  激しい掃射により反撃がままならない。1ラウンドに攻撃ロールを行えるのは分隊長を含め最大3名までとする。
"""
new65 = """- 機銃制圧：
  激しい掃射により反撃がままならない。1ラウンドに攻撃ロールを行えるのは分隊長を含め最大3名までとする。
- 鹵獲：
  この車両は有人車両として扱う。生命点が1のときにCore v1.01の【ネゴシエーション】に成功した場合、乗員を【捕虜】にし、車両を【鹵獲】できる。以後はCore v1.01の【車両】の鹵獲効果を適用する。
"""
if s.count(old65) != 1:
    raise SystemExit(f"event65 anchor count={s.count(old65)}")
s = s.replace(old65, new65, 1)

old66 = """- 追い込み火力：
  残り生命点が2以下になった場合、攻撃回数は2になる。
"""
new66 = """- 追い込み火力：
  残り生命点が2以下になった場合、攻撃回数は2になる。
- 鹵獲：
  この車両は有人車両として扱う。生命点が1のときにCore v1.01の【ネゴシエーション】に成功した場合、乗員を【捕虜】にし、車両を【鹵獲】できる。以後はCore v1.01の【車両】の鹵獲効果を適用する。
"""
if s.count(old66) != 1:
    raise SystemExit(f"event66 anchor count={s.count(old66)}")
s = s.replace(old66, new66, 1)

old_final = """- 装甲車両の生命点を0にした時点で車両は炎上し、民兵は潰走する。その時点で戦闘は終了する。
"""
new_final = """- 鹵獲：対戦車砲装甲車両は有人車両として扱う。生命点が1のときにCore v1.01の【ネゴシエーション】に成功した場合、乗員を【捕虜】にし、車両を【鹵獲】して戦闘から除外する。この場合、車両を撃破したわけではないため民兵は潰走せず、残存民兵との戦闘を継続する。ここは最終イベントであるため、Core v1.01の【車両】鹵獲によるd66一の位補正を使用する機会は発生しない。
- 装甲車両の生命点を0にした時点で車両は炎上し、民兵は潰走する。その時点で戦闘は終了する。
"""
if s.count(old_final) != 1:
    raise SystemExit(f"final vehicle anchor count={s.count(old_final)}")
s = s.replace(old_final, new_final, 1)

# Clarify Black Sun application/order for captured vehicle route control.
anchor = """この手順を繰り返し、最終イベントに到達した時点で、作戦は終局局面へ移行する。
"""
insert = """この手順を繰り返し、最終イベントに到達した時点で、作戦は終局局面へ移行する。

- 鹵獲車両による進路補正：Core v1.01の【車両】を鹵獲している場合、上記手順4で他の修正・固定・振り直し等を処理した後、d66の一の位を+1または-1して最終結果を確定できる。この補正後の結果を手順5の最終イベント出現判定にも使用する。4枚目の中間イベントまたは最終イベントに到達した時点で、その車両の鹵獲効果は終了する。
"""
if s.count(anchor) != 1:
    raise SystemExit(f"map flow anchor count={s.count(anchor)}")
s = s.replace(anchor, insert, 1)
scenario.write_text(s, encoding="utf-8")

p0 = Path("docs/CORE_V1_01_P0_DECISIONS.md")
p = p0.read_text(encoding="utf-8")
heading = "## 13. 【ネゴシエーション】対象と【鹵獲】 — 承認・反映済み"
section = """

## 13. 【ネゴシエーション】対象と【鹵獲】 — 承認・反映済み

ユーザー判断により、人物以外の高脅威目標に対する【ネゴシエーション】と【鹵獲】を次のように整理する。

- バリケード、無人設備、無人兵器など、人が介在しない対象は【ネゴシエーション】対象外とする。
- 人物に加え、人間の乗員・操作員が介在する車両・固定兵装は【ネゴシエーション】対象とする。
- 有人車両・有人固定兵装の生命点が1のときに【ネゴシエーション】へ成功した場合、乗員・操作員を【捕虜】にし、装備を【鹵獲】する。
- 生命点0で撃破・破壊された装備は【鹵獲】できない。
- 【鹵獲】対象は即座に戦闘から除外する。他の敵が残っている場合は戦闘を継続する。
- 車両の標準鹵獲効果は、次の固定イベントまでd66マップ決定後の一の位を±1できることとする。一の位は1～6の範囲内とし、1回のマップ決定につき1回まで使用できる。
- 車両の補正は他の強制修正・固定・振り直し等の後に適用し、補正後の結果を固定イベント出現判定にも使用する。
- 同時に有効な車両鹵獲効果は1台分のみとする。
- 固定兵装の標準鹵獲効果は、弾薬・部品の回収による弾倉+1個とする。その後、固定兵装は使用不能として扱う。
- 車両搭載兵装など1対象が車両・固定兵装の両方に該当する場合、特記がなければ車両効果のみ適用し、弾倉+1は重複しない。
- シナリオ固有の鹵獲効果がある場合は、Coreの標準効果よりシナリオ記載を優先する。

この設計により、HP1で攻撃を止めて指揮点を使うか、HP0まで撃破するかという戦術的選択を作りつつ、修理・燃料・乗員配置などの追加管理はCoreへ導入しない。
"""
if heading not in p:
    p = p.rstrip() + section + "\n"
p0.write_text(p, encoding="utf-8")

audit = Path("docs/SCENARIO_V1_01_RESOURCE_BALANCE_AUDIT.md")
a = audit.read_text(encoding="utf-8")
heading2 = "## 52. 【鹵獲】導入とBlack Sun車両への適用 — 採用済み"
section2 = """

## 52. 【鹵獲】導入とBlack Sun車両への適用 — 採用済み

ユーザー承認により、有人車両・有人固定兵装を【ネゴシエーション】から【鹵獲】へ接続するCore共通処理を導入し、Black Sunへ適用する。

- 人が介在しないバリケードは【ネゴシエーション】対象外のままとする。
- 出目65【つぎはぎだらけの武装トラック】と出目66【即席装甲ガン・トラック】へ【車両】属性を追加し、有人車両として鹵獲可能であることを明記する。
- 両車両は生命点1で【ネゴシエーション】に成功した場合、乗員を【捕虜】、車両を【鹵獲】とする。
- 鹵獲車両は次の固定イベントまで、d66の他の修正等を処理した後に一の位を±1できる。この補正後の出目を最終イベント出現判定にも使用する。
- 3周目最終イベントの【対戦車砲装甲車両】も有人車両として鹵獲可能とする。ただし最終イベント中のため、鹵獲後にd66を振る機会はなく、車両の標準進路補正は実質的に発生しない。
- 3周目最終イベントで車両を鹵獲した場合は「生命点0による撃破」ではないため、民兵の潰走条件は発生せず、残存民兵との戦闘を継続する。
- 現行Black Sunには独立した有人固定兵装の高脅威目標がないため、固定兵装の弾倉+1効果は将来のシナリオ拡張用Core規定として保持する。

設計上は、撃破による即時安全確保と、HP1で攻撃を止めて指揮点を消費し鹵獲利益を狙う選択が生まれる。車両の効果を進路操作、固定兵装を小規模な弾薬回収に分けることで、同じ【鹵獲】でも対象種別ごとに異なる価値を持たせる。
"""
if heading2 not in a:
    a = a.rstrip() + section2 + "\n"
audit.write_text(a, encoding="utf-8")
